"""Emit the Node.js resource layer (ESM + .d.ts typings) from the catalog."""
from __future__ import annotations

import os
from typing import Any, Dict, List

from . import catalog as cat

HEADER = """// {title}.
// Generated from spec/tino-userapi-catalog.json by tools/generate-sdk.py — do not edit by hand.

import {{ Resource }} from './base.js';

/** {title} — {count} operations. */
export class {class_name} extends Resource {{"""


def _jsdoc(operation: Dict[str, Any]) -> List[str]:
    lines = ["  /**"]
    for line in cat.doc_lines(operation):
        lines.append(("   * " + line).rstrip())
    for param in cat.path_params(operation):
        description = (param.get("description") or "").replace("\n", " ")
        lines.append(f"   * @param {{string|number}} {cat.js_arg(param['name'])} {description}".rstrip())
    if cat.has_body(operation):
        lines.append("   * @param {object} [body] Request payload.")
    lines.append("   * @param {object} [query] Extra query-string parameters.")
    lines.append("   * @returns {Promise<any>}")
    lines.append("   */")
    return lines


def _method(operation: Dict[str, Any]) -> List[str]:
    name = cat.camel(operation["name"])
    params = cat.path_params(operation)
    args = [cat.js_arg(p["name"]) for p in params]
    if cat.has_body(operation):
        args.append("body = undefined")
    args.append("query = {}")

    lines = _jsdoc(operation)
    lines.append("  " + name + "(" + ", ".join(args) + ") {")

    if params:
        mapping = ", ".join(f"{p['name']}: {cat.js_arg(p['name'])}" for p in params)
        lines.append(f"    const path = this._path('{operation['path']}', {{ {mapping} }});")
        path_expr = "path"
    else:
        path_expr = f"'{operation['path']}'"

    options = ["query"]
    if cat.has_body(operation):
        options.append("body")
    if not operation.get("auth", True):
        options.append("authenticated: false")
    lines.append(f"    return this._call('{operation['method']}', {path_expr}, {{ {', '.join(options)} }});")
    lines.append("  }")
    lines.append("")
    return lines


def _dts(group: str, operations: List[Dict[str, Any]]) -> List[str]:
    class_name = cat.pascal(group) + "Resource"
    lines = [
        f"// Type declarations for {cat.GROUP_TITLES.get(group, group)}.",
        "// Generated by tools/generate-sdk.py — do not edit by hand.",
        "",
        "import { Resource } from './base.js';",
        "",
        f"export declare class {class_name} extends Resource {{",
    ]
    for operation in operations:
        args = [f"{cat.js_arg(p['name'])}: string | number" for p in cat.path_params(operation)]
        if cat.has_body(operation):
            args.append("body?: Record<string, any>")
        args.append("query?: Record<string, any>")
        lines.append(f"  /** {operation['method']} {operation['path']} */")
        lines.append(f"  {cat.camel(operation['name'])}({', '.join(args)}): Promise<any>;")
    lines.append("}")
    return lines


def _prune(out_dir: str, keep: set) -> None:
    """Delete generated files for groups the catalog no longer contains."""
    for name in os.listdir(out_dir):
        if name not in keep and os.path.isfile(os.path.join(out_dir, name)):
            os.remove(os.path.join(out_dir, name))


def emit(catalog: Dict[str, Any], root: str) -> List[str]:
    grouped = cat.by_group(catalog)
    out_dir = os.path.join(root, "sdk", "nodejs", "src", "resources")
    os.makedirs(out_dir, exist_ok=True)
    written: List[str] = []

    for group, operations in sorted(grouped.items()):
        class_name = cat.pascal(group) + "Resource"
        title = cat.GROUP_TITLES.get(group, group)
        lines = [HEADER.format(title=title, class_name=class_name, count=len(operations))]
        for operation in operations:
            lines.extend(_method(operation))
        lines.append("}")
        path = os.path.join(out_dir, cat.snake(group).replace("_", "-") + ".js")
        with open(path, "w", encoding="utf-8") as handle:
            handle.write("\n".join(lines).rstrip() + "\n")
        written.append(path)

        dts_path = path[:-3] + ".d.ts"
        with open(dts_path, "w", encoding="utf-8") as handle:
            handle.write("\n".join(_dts(group, operations)) + "\n")
        written.append(dts_path)

    index = [
        "// Resource groups exposed on TinoClient.",
        "// Generated by tools/generate-sdk.py — do not edit by hand.",
        "",
        "import { Resource } from './base.js';",
    ]
    for group in sorted(grouped):
        module = cat.snake(group).replace("_", "-")
        index.append(f"import {{ {cat.pascal(group)}Resource }} from './{module}.js';")
    index.append("")
    index.append("export { Resource };")
    index.append("export const RESOURCE_CLASSES = {")
    for group in sorted(grouped):
        index.append(f"  {cat.camel(group)}: {cat.pascal(group)}Resource,")
    index.append("};")
    index.append("")
    index.append("export {")
    for group in sorted(grouped):
        index.append(f"  {cat.pascal(group)}Resource,")
    index.append("};")
    _prune(out_dir, {os.path.basename(p) for p in written}
           | {"base.js", "base.d.ts", "index.js", "index.d.ts"})
    index_path = os.path.join(out_dir, "index.js")
    with open(index_path, "w", encoding="utf-8") as handle:
        handle.write("\n".join(index) + "\n")
    written.append(index_path)
    return written
